import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Incremental Compilation","description":"A few dozen lines of code expand, through their #includes, to tens or hundreds of thousands: #include alone is thousands of lines. Compiling all of it after every keystroke takes seconds.","frontmatter":{"head":[["meta",{"property":"og:title","content":"Incremental Compilation | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/design/incremental-parse"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/design/incremental-parse"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/incremental-parse"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/incremental-parse"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/incremental-parse"}],["meta",{"property":"og:description","content":"A few dozen lines of code expand, through their #includes, to tens or hundreds of thousands: #include alone is thousands of lines. Compiling all of it after every keystroke takes seconds."}]]},"headers":[],"relativePath":"clice/design/incremental-parse.md","filePath":"en/clice/design/incremental-parse.md","lastUpdated":1794738697000}'),n={name:"clice/design/incremental-parse.md"};function o(l,e,h,r,d,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="incremental-compilation" tabindex="-1">Incremental Compilation <a class="header-anchor" href="#incremental-compilation" aria-label="Permalink to &quot;Incremental Compilation&quot;">​</a></h1><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>A few dozen lines of code expand, through their <code>#include</code>s, to tens or hundreds of thousands: <code>#include &lt;vector&gt;</code> alone is thousands of lines. Compiling all of it after every keystroke takes seconds. But the includes at the top of a file rarely change while the code below changes constantly:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;vector&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;string&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;project/config.h&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ── preamble ↑ changes slowly, its compile is cached ──</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ── code ↓ changes constantly, recompiled each time   ──</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> process</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>So C++ language servers split a file into its <strong>preamble</strong>, the directives at the top, compiled once into a precompiled header (PCH), and the rest, recompiled over the PCH. clangd does too, with shortcomings in how it keeps and checks the PCH: it holds preambles in memory, which grows over long sessions (<a href="https://github.com/clangd/clangd/issues/251" target="_blank" rel="noreferrer">clangd#251</a>); its PCH files are temporary files a crash leaves behind (<a href="https://github.com/clangd/clangd/issues/209" target="_blank" rel="noreferrer">clangd#209</a>); a header touched without a change rebuilds the PCH; and nothing survives a restart.</p><p>clice keeps PCHs on disk, named by content; rebuilds one only when a dependency&#39;s content changed; compiles when a request needs the result, not on every edit; and never builds a PCH from a header name still being typed.</p><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h2><h3 id="the-preamble" tabindex="-1">The Preamble <a class="header-anchor" href="#the-preamble" aria-label="Permalink to &quot;The Preamble&quot;">​</a></h3><p>The preamble runs from the top of the file to just before the first line that is not a directive. In a module unit it is the whole global module fragment, up to the module declaration. It ends early before a <code>#pragma</code> push it does not pop (<code>push_macro</code>, <code>pack(push)</code>, …), since a PCH keeps none of those stacks, and before a header name still being typed, such as an unclosed <code>#include &quot;lib</code>: the finished directives above it stay precompiled, and the unfinished line parses with the body, where it reports its own error. A PCH built from a half-typed include would flood the file with false errors. In a global module fragment, a push followed by an include or code of the fragment&#39;s own leaves no preamble, and so does a header name being typed in a fragment that declares anything itself: the body would parse those ahead of the module declaration.</p><p>The boundary is found by a lexical scan, without a preprocessor.</p><h3 id="what-the-pch-does-for-the-body" tabindex="-1">What the PCH Does for the Body <a class="header-anchor" href="#what-the-pch-does-for-the-body" aria-label="Permalink to &quot;What the PCH Does for the Body&quot;">​</a></h3><p>The PCH build also instantiates the function templates the preamble itself uses — the members of <code>std::vector&lt;int&gt;</code> a header&#39;s inline function calls — so the compile of the body finds them done, often most of the work an edit waits for.</p><p>Outside module units and the files importing a module, the PCH skips the bodies of the functions in the files the preamble includes, as clangd&#39;s does, keeping the <code>constexpr</code>, <code>consteval</code> and <code>auto</code> functions the compiler needs, and the templates forwarding their arguments (<code>make_unique</code>), whose bodies hold what features read through such a call, such as the parameter names an inlay hint shows. The body&#39;s compile then instantiates almost no header template&#39;s body, the bulk of an edit&#39;s work on template-heavy code, and holds a far smaller AST. What those bodies would report comes from the background index, which compiles every body: its run of the file brings back the diagnostics the editor&#39;s compile skipped, shown while the buffer holds the text it read. A rule&#39;s <code>skip_function_body</code> turns the skipping off, or extends it to every compile but the file&#39;s own, and to the build of the file&#39;s module or precompiled header.</p><h3 id="is-the-pch-still-good" tabindex="-1">Is the PCH Still Good? <a class="header-anchor" href="#is-the-pch-still-good" aria-label="Permalink to &quot;Is the PCH Still Good?&quot;">​</a></h3><p>A PCH is stale when the content of a file it read changed. Comparing modification times alone rebuilds on every touch — a build tool&#39;s scan, a branch switch, an editor&#39;s autosave — and hashing every dependency on every check reads hundreds of headers. clice does both, in two layers, once, in the file table every freshness check shares (PCH and module validation, index staleness, disk polling):</p><ol><li><strong>Stat.</strong> The table keeps one observation per file: the size and mtime a read saw, and the hash of the bytes read. A stat equal to it means the hash is known without reading.</li><li><strong>Hash.</strong> A file whose stat differs is read and hashed, which becomes its new observation. The PCH is stale only when the hash differs from the one of the bytes it was built from.</li></ol><p>The bytes a build read are hashed from the compiler&#39;s own buffers, so a file changed during the build is never taken for what it read.</p><h3 id="compiling-when-asked" tabindex="-1">Compiling When Asked <a class="header-anchor" href="#compiling-when-asked" aria-label="Permalink to &quot;Compiling When Asked&quot;">​</a></h3><p>An edit only updates the buffer and marks its compile out of date; the compile runs when a request needs the result — a hover, completion, semantic tokens. A dozen keystrokes a second do not cost a dozen compiles. Changes on disk mark the open files depending on them out of date too, found by the server&#39;s polls, with the two-layer check before every compile as the backstop.</p><p>After a dependency changes — a saved header, a file a poll finds changed — open files do not wait for a request: a client that pulls diagnostics is asked to pull them again when it takes that request, and for one that does not pull, clice compiles the stale files and pushes theirs. Saves in a row compile an open file twice at most. The PCHs of files nobody has open are rebuilt when one is opened.</p><h3 id="content-addressed-storage" tabindex="-1">Content-Addressed Storage <a class="header-anchor" href="#content-addressed-storage" aria-label="Permalink to &quot;Content-Addressed Storage&quot;">​</a></h3><p>A PCH file is named by the hash of its preamble&#39;s text, the frontend-relevant flags, the directories and the clang version, so files whose preambles and commands agree share one file — unless the preamble defines or tests a macro, which places the PCH in the file that built it and adds that file&#39;s path to the name. Its record — the path, the hash, the boundary, what it read — is saved in the index database, so a restart checks each PCH and rebuilds only the stale ones. A changed preamble gets a new file; the old one is evicted when the cache outgrows its budget, coldest first.</p><p>A precompiled header the build declares — CMake&#39;s per target, or any command writing one that others read — is the one chain clice builds: a file reading it builds its preamble&#39;s PCH over it, so a change to its own preamble never parses the declared header&#39;s contents again. The declared PCH is built once and both the editor and the background index load it.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><ul><li><strong>Why two layers instead of hashing alone?</strong> Hashing every dependency on every check reads hundreds of headers. The stat layer narrows hashing to the files touched since the last look, usually none.</li><li><strong>Why compile when asked instead of on every change?</strong> clice keeps every file&#39;s PCH on disk, far more than clangd keeps in memory. A changed header can invalidate many of them; rebuilding them all at once would be an unacceptable volume, so only the PCH of the file someone asks about is rebuilt.</li><li><strong>Is a PCH on disk slower than one in memory?</strong> Clang maps the file and reads only the nodes a compile uses, so loading costs about the same either way; on disk it survives restarts, holds no process memory, and is shared between files.</li></ul><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><strong>A changed dependency rebuilds the whole PCH.</strong> Only a precompiled header the build declares stays apart.</li><li><strong>The completeness check covers header names alone.</strong> Other half-typed directives, such as a <code>#define</code> whose value is being typed, build a PCH as they stand; the edit completing them rebuilds it.</li><li><strong>No PCH for a global module fragment that imports.</strong> A module unit whose fragment imports a module, usually through a header, parses its whole preamble on every edit: a PCH keeps no record that the fragment was open, and the module declaration after it would hide the modules imported there.</li><li><strong>Templates the preamble instantiates see only the preamble.</strong> The PCH instantiates the templates its headers use where the preamble ends, while a compiler does so at the end of the file, after the file&#39;s own declarations. An instantiation failing at the preamble&#39;s end is left to the file&#39;s end; one succeeding there differs from the compiler&#39;s in rare cases, whose errors the background index shows instead.</li><li><strong>Errors inside headers&#39; function bodies wait for the background index</strong>, outside module units and the files importing a module, which parse every body. They show once it has compiled the file as saved, and an edit takes them down until the next save, as do the warnings about unused declarations. They never show where the background index does not compile the file as the editor does: with background indexing off, on a header compiled in its includer&#39;s context, on a file no database lists, or in a context the user chose. clang-tidy checks that read the bodies of called functions, such as <code>bugprone-exception-escape</code>, find less in the editor than <code>clice lint</code>.</li></ul>`,27)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
